/** Limits a number to the inclusive range [min, max]. */
export function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}
EOF
cat > test/clamp.test.ts <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { clamp } from '../src/clamp.ts';

test('returns values inside the range unchanged', () => {
  assert.equal(clamp(5, 0, 10), 5);
  assert.equal(clamp(0, 0, 10), 0);
  assert.equal(clamp(10, 0, 10), 10);
});

test('clamps below min and above max', () => {
  assert.equal(clamp(-3, 0, 10), 0);
  assert.equal(clamp(42, 0, 10), 10);
});

test('works with negative ranges', () => {
  assert.equal(clamp(-7, -5, -1), -5);
  assert.equal(clamp(0, -5, -1), -1);
});
